 models.magnification=(l,v)=>{const actual=pick([5,10,20,25,40,50]),factor=pick([100,200,400,600]),image=actual*factor/1000,inverse=v%3;return number(inverse===0?`На микрофотографии клетка длиной ${actual} мкм имеет длину ${fmt(image)} мм. Найдите увеличение.`:inverse===1?`Длина изображения клетки ${fmt(image)} мм, увеличение ${factor}. Найдите настоящую длину клетки в мкм.`:`Длина клетки ${actual} мкм. Какой будет длина изображения в миллиметрах при увеличении ${factor}?`,inverse===0?factor:inverse===1?actual:image,inverse===0?'раз':inverse===1?'мкм':'мм','Увеличение — отношение размера изображения к реальному размеру. Сначала приведите их к одинаковым единицам.','M = Lизобр/Lреал; 1 мм = 1000 мкм',[`Размер изображения ${fmt(image)} мм = ${fmt(image*1000)} мкм.`,inverse===0?`M = ${fmt(image*1000)}/${actual}.`:inverse===1?`L = ${fmt(image*1000)}/${factor}.`:`Lизобр = ${actual} · ${factor}/1000 мм.`],{kind:'magnification',actual,factor,inverse})};
 models.population=(l,v)=>{const start=rnd(10,30)*10,b=rnd(10,40),d=rnd(2,9),incoming=l===3?rnd(5,15):0,outgoing=l===3?rnd(1,4):0;return number(`В популяции было ${start} особей. За период родилось ${b}, погибло ${d}${l===3?`, прибыло ${incoming}, выбыло ${outgoing}`:''}. ${l===3?'Других изменений нет.':'Миграции не было.'} Сколько особей стало?`,start+b-d+incoming-outgoing,'особей','Численность увеличивается при рождении и иммиграции, уменьшается при гибели и эмиграции.','N₂ = N₁ + рождения − гибель + иммиграция − эмиграция',[`N₂ = ${start} + ${b} − ${d} + ${incoming} − ${outgoing}.`],{kind:'population',start,b,d,incoming,outgoing})};
 models.energy=(l,v)=>{const base=pick([1000,2000,5000,10000]),p=pick([10,20]),steps=l===3?2:1;return number(`Энергия на исходном трофическом уровне ${base} кДж. В этой модели на следующий уровень передаётся ${p}% энергии. Сколько энергии окажется через ${steps===1?'один уровень':'два уровня'}?`,base*(p/100)**steps,'кДж','Используйте долю передачи, данную в условии. Она не является универсальной константой для всех реальных экосистем.','Eслед = Eпред · доля передачи',[`После первого перехода: ${base} · ${p}/100 = ${base*p/100} кДж.`,...(steps===2?[`После второго перехода: ${base*p/100} · ${p}/100.`]:[])],{kind:'energy',base,p,steps})};
 models.efficiency=(l,v)=>{const base=pick([1000,2000,4000]),p=pick([5,10,15,20]);return number(`На предыдущем трофическом уровне запасено ${base} кДж, в прирост биомассы следующего уровня перешло ${base*p/100} кДж. Найдите эффективность переноса энергии в процентах.`,p,'%','Эффективность переноса — доля энергии предыдущего уровня, перешедшая на следующий.','η = Eслед/Eпред · 100%',[`η = ${base*p/100}/${base} · 100%.`],{kind:'efficiency',base,p})};
 models.pulse=(l,v)=>{const count=pick([15,18,20,21,24]),seconds=pick([15,20,30]),rate=count*60/seconds,time=l===3?pick([3,4,5]):1;return number(`За ${seconds} с подсчитали ${count} сердечных сокращений. Считая частоту постоянной, сколько сокращений будет за ${time} мин?`,rate*time,'сокращений','Для пересчёта на минуту число сокращений делят на время наблюдения в секундах и умножают на 60.','N = число за интервал · 60/секунды · минуты',[`За минуту: ${count} · 60/${seconds} = ${rate}.`,...(time>1?[`За ${time} мин: ${rate} · ${time}.`]:[])],{kind:'pulse',count,seconds,time})};
 models.ventilation=(l,v)=>{const volume=pick([.4,.5,.6,.8]),frequency=pick([10,12,15,20]),target=v%2;return number(target?`Минутный объём дыхания ${fmt(volume*frequency)} л/мин, частота ${frequency} вдохов/мин. Найдите дыхательный объём.`:`Дыхательный объём ${fmt(volume)} л, частота ${frequency} вдохов/мин. Найдите минутный объём дыхания.`,target?volume:volume*frequency,target?'л':'л/мин','Минутный объём дыхания равен произведению дыхательного объёма на частоту дыхания.','Vмин = Vдых · f',[target?`Vдых = ${fmt(volume*frequency)}/${frequency}.`:`Vмин = ${fmt(volume)} · ${frequency}.`],{kind:'ventilation',volume,frequency,target})};
 models.dna=(l,v)=>{const p=pick([10,15,20,25,30,35,40]),target=v%2;return number(`В двуцепочечной ДНК аденин составляет ${p}% всех нуклеотидов. Найдите долю ${target?'гуанина':'тимина'} среди всех нуклеотидов.`,target?50-p:p,'%','В двуцепочечной ДНК A = T, G = C. Сумма долей всех четырёх оснований равна 100%.',target?'G = (100% − A − T)/2':'T = A',[`T = A = ${p}%.`,...(target?[`G = (100 − ${p} − ${p})/2.`]:[])],{kind:'dna',p,target})};
